UPDATE garage_zone
SET version = version + 1
, zone_code = #{zone.zoneCode}
, zone_name = #{zone.zoneName}
, parent_id = #{zone.parentId}
, level = #{zone.level}
, sort_order = #{zone.sortOrder}
, status = #{zone.status}
WHERE id = #{zone.id}
  AND version = #{zone.version}

UPDATE garage_zone
SET level = level + #{delta}
WHERE id IN

    #{id}
